"""Need-led pages and honest launch states for proposed community initiatives."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json

ROOT=Path(__file__).resolve().parent.parent
CONFIG=json.loads((Path(__file__).parent/'growth-content.json').read_text())
NEEDS=[
 ('fit-stark','Fit & stark','Kraft, Ausdauer und Performance.','Für ambitioniertes Training und sportliche Ziele.','/fit-stark/','01'),
 ('gesund-beweglich','Gesund & beweglich','Fit bleiben – in jedem Alter.','Kraft erhalten, Beweglichkeit entwickeln und bewusst einsteigen.','/gesund-beweglich/','02'),
 ('neu-anfangen','Neu anfangen','Dein Einstieg ohne Druck.','Persönliche Orientierung und ein Training, das zu dir passt.','/neu-anfangen/','03'),
 ('gemeinsam','Gemeinsam trainieren','Mehr Motivation. Mehr Gemeinschaft.','Entdecke die Challenge, Friends & Family und unsere Club-Ideen.','/community/','04')
]

def validated_stories():
    stories=[]
    for s in CONFIG['testimonials']:
        required=['name','age','goal','quote','image','source','approved_for_publication']
        if any(k not in s for k in required) or s['approved_for_publication'] is not True:
            raise ValueError('Member stories require source, real photo and explicit publication approval.')
        if any(not isinstance(s[k],str) or not s[k].strip() for k in ['name','goal','quote','image','source']):
            raise ValueError('Member stories require non-empty verified content and source.')
        path=ROOT/s['image']; resolved=path.resolve()
        if ROOT not in resolved.parents or not path.is_file() or type(s['age']) is not int or not 18<=s['age']<=120:
            raise ValueError('Invalid member story asset or age.')
        stories.append(s)
    if CONFIG.get('member_count') is not None and (type(CONFIG['member_count']) is not int or CONFIG['member_count']<1 or not str(CONFIG.get('member_count_source','')).strip()):
        raise ValueError('A member count needs a confirmed positive value and source.')
    if CONFIG['family']['status']!='planned':
        raise ValueError('An active family program needs confirmed terms and an implemented participation flow.')
    return stories

class Growth:
    def __init__(self,ctx):
        self.c=ctx
        self.team={p['slug']:p for p in ctx['TEAM']}
        self.g=ctx['GALLERY'];self.stories=validated_stories()
    def b(self,*a,**kw):return self.c['button'](*a,**kw)
    def link(self,*a):return self.c['textlink'](*a)
    def image(self,*a,**kw):return self.c['img'](*a,**kw)
    def section(self,id,body,cls=''):
        return f'<section class="section growth-section {cls}" id="{id}"><div class="wrap">{body}</div></section>'
    def heading(self,eyebrow,title,lead=''):
        return f'<div class="section-head"><div><p class="eyebrow">{eyebrow}</p><h2>{title}</h2></div>'+ (f'<p class="muted">{lead}</p>' if lead else '')+'</div>'
    def needs(self,compact=False):
        cards=''.join(f'<a class="need-card need-{slug}" href="{url}"><span class="need-number">{n} / DEIN ZIEL</span><h3>{title}</h3><strong>{subtitle}</strong><p>{text}</p><span class="need-arrow" aria-hidden="true">↗</span></a>' for slug,title,subtitle,text,url,n in NEEDS)
        return self.section('dein-ziel',self.heading('Dein Ziel gibt die Richtung vor.','Was möchtest du<br>erreichen?','Dein Alter ist keine Kategorie. Dein Ziel ist der Anfang.')+f'<nav class="needs-grid" aria-label="Training nach deinem Ziel">{cards}</nav>','needs-section'+(' compact' if compact else ''))
    def personal_proof(self):
        if self.stories:
            cards=''.join(f'<figure class="member-story">{self.image(s["image"],s["name"])}<figcaption><p class="eyebrow">{escape(s["name"])} · {s["age"]}</p><p class="story-goal">{escape(s["goal"])}</p><blockquote>„{escape(s["quote"])}“</blockquote></figcaption></figure>' for s in self.stories)
            return self.section('menschen',self.heading('Menschen wie du.','Warum Menschen<br>bei 17/7 bleiben.')+'<div class="stories-grid">'+cards+'</div>')
        p=self.team['beatrice-ulonska']
        return self.section('menschen',f'<div class="human-proof"><div class="human-photo">{self.image(p["asset"],"Beatrice Ulonska, Personal Trainerin im Performance Gym",position="50% 50%")}</div><div class="human-copy"><p class="eyebrow">Persönlichkeit ist kein Extra.</p><h2>Ein Ziel.<br>Ein Mensch an<br>deiner Seite.</h2><blockquote>„{escape(p["overview_excerpt"])}“</blockquote><p class="human-name">Beatrice Ulonska <span>Personal Trainerin bei 17/7</span></p><p>Bring deine Fragen mit. Unsere Personal Trainer stellen sich mit ihren eigenen Profilen vor – damit aus einem ersten Eindruck ein persönlicher Kontakt wird.</p>{self.link('Beatrice kennenlernen','/staff-member/beatrice-ulonska/')}</div></div>','light')
    def team_section(self):
        cards=[]
        for slug in ['guido-leffler','thomas-rossbroich','maike']:
            p=self.team[slug]
            note={'guido-leffler':'Dein Ansprechpartner in der Studioleitung.','thomas-rossbroich':'„Das Geheimnis des Erfolgs ist anzufangen!“','maike':'Ein bekanntes Gesicht im Team vor Ort.'}[slug]
            cards.append(f'<article class="human-card"><a href="/staff-member/{slug}/" class="human-card-photo">{self.image(p["asset"],p["name"],position=p.get("recommended_object_position"))}</a><div><p class="eyebrow">{escape(p["role"])}</p><h3>{escape(p["name"])}</h3><p>{note}</p>{self.link('Profil kennenlernen','/staff-member/'+slug+'/')}</div></article>')
        return self.section('dein-team',self.heading('Inhabergeführt. Persönliche Ansprechpartner.','Kein anonymes Studio.<br>Menschen, die du kennst.','Ob erster Besuch oder feste Routine: Lerne die Menschen hinter 17/7 kennen.')+'<div class="human-cards">'+''.join(cards)+'</div><div class="actions">'+self.link('Das ganze Team kennenlernen','/unser-team/')+'</div>')
    def training_section(self):
        items=[('Kraft','Freie Gewichte und geführte Geräte.','/training/#kraft',self.g[1]),('Cardio','Deine Ausdauer. In deinem Tempo.','/training/#cardio',self.g[6]),('Functional','Bewegung mit vielen Möglichkeiten.','/training/#functional',self.g[0]),('Mobility','Bewusster bewegen. Ausgleich finden.','/training/#mobility',self.g[8])]
        cards=''.join(f'<a href="{url}" class="training-mini"><div>{self.image(photo)}</div><span><h3>{title}</h3><p>{desc}</p><i aria-hidden="true">↗</i></span></a>' for title,desc,url,photo in items)
