    def clubs(self,full=False):
        cards=[]
        for i,c in enumerate(CONFIG['clubs']):
            # Ideas have no invented schedule, included benefit or bookable class.
            if c['status']!='planned':raise ValueError('An active club needs an explicitly implemented schedule/booking integration.')
            anchor=c['id'];name=escape(c['name']);url='/contact/?thema='+quote(c['name'])+'#contact-form'
            extra=f'<p class="club-description">{escape(c["description"])}</p><p class="club-focus">{escape(c["focus"])}</p>' if full else ''
            cards.append(f'<article class="club-card" id="{anchor}"><div class="club-card-top"><span>0{i+1}</span><span class="launch-badge">In Planung</span></div><h3>{name}</h3><p class="club-headline">{escape(c["headline"])}</p>{extra}{self.link("Interesse mitteilen" if full else "Format entdecken",url if full else "/community/#"+anchor)}</article>')
        return '<div class="club-grid">'+''.join(cards)+'</div>'
